//! Continuous integration for the Rust SDK for Dagger, built with the SDK itself.
//!
//! Every function runs inside the Dagger engine, so the same calls work from a laptop, a CI
//! runner, or a managed engine. Orchestration, secrets, and engine provisioning stay outside
//! the module, in `.dagger/engine.sh` and the pipelines that call it. The one engine the
//! module starts itself is the later-engine step's, a service of the engine that runs it.
//! Publishing stays outside too: `package` prepares a release's archives, and `published`
//! proves the release afterwards.

// Generated by `dagger generate`; regenerate after changing exported items.
pub mod dagger_generated;

use std::collections::{BTreeMap, BTreeSet};

use dagger_generated::ModuleContext;
use dagger_sdk::{
    CacheSharingMode, Container, ContainerAsServiceOpts, ContainerWithExecOpts,
    ContainerWithMountedCacheOpts, Directory, File, ModuleError, Query, QueryError, QueryHttpOpts,
    ReturnType, Service,
};
use serde_json::Value;

/// The runtime's digest-pinned builder, so CI compiles with the inputs module builds use.
const RUST_IMAGE: &str =
    "rust:1.99.1-bookworm@sha256:e12566d5abc17a0da741628782cdb504b68b8961f5bfcf677936bf3e8b32de29";
/// The Go release the runtime's `go.mod` names.
const GO_IMAGE: &str = "golang:1.26.1-bookworm@sha256:ab3d6955bbc813a0f3fdf220c1d817dd89c0b3f283777db8ece4a32fe7858edd";
const CARGO_DENY_VERSION: &str = "0.19.9";
/// How much of a failed step's output an error keeps, from the end.
const OUTPUT_TAIL: usize = 16 * 1024;
const GATES_PASSED: &str = "cargo fmt, check, clippy, doc, test (all and no default features), \
    deny and the generated-output check, and the runtime's Go tests passed";
/// The repository the acceptance installs the runtime from and builds the client against.
const REPOSITORY: &str = "github.com/tokeira/dagger-rust-sdk";
/// The release of the CLI the acceptance drives the engine with: the one the SDK targets.
const DAGGER_VERSION: &str = "1.0.0-beta.27";
/// The engine image of that release, pinned by digest as `.dagger/engine.sh` pins it.
const ENGINE_IMAGE: &str = "registry.dagger.io/engine:v1.0.0-beta.27@sha256:ad121f720ed9bfb8e740f99dd783fa8472965a5e262fc64ff3ef2634cea1e6dd";
/// The later release that the later-engine step's engine reports.
const LATER_VERSION: &str = "1.0.0-beta.28";
/// The version the later-engine step's engine reports for itself. The override replaces
/// the whole version string, so it carries the build metadata a release engine adds.
const LATER_ENGINE_VERSION: &str = "1.0.0-beta.28+1a2b3c4d";
/// The description of the acceptance's gate module: the crate documentation of
/// `acceptance/gate.rs`.
const GATE_DESCRIPTION: &str = "Release-gate module authored after initialization.\n\n\
    Its crate documentation describes the module, which the acceptance reads back.";
/// Introduces the README's module block, which the acceptance runs as written.
const README_MARKER: &str = "<!-- The ci module's acceptance runs the module below as written. -->";
/// The manifest of the application that gets module clients, before it has any.
const APP_MANIFEST: &str = "[package]\nname = \"app\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\
    publish = false\n\n[dependencies]\n\
    tokio = { version = \"1.35.1\", features = [\"macros\", \"rt-multi-thread\"] }\n";
/// The line the application prints once both of its clients answered: the greeter's
/// greeting, then the URL and the retries of naming-app's fetcher.
const APP_ANSWER: &str = "ACCEPTANCE-MODULE-CLIENTS-OK hi, app; https://example.invalid 3";
/// The application's local client as `dagger.toml` records it, from the workspace root.
const NAMING_APP: &str = "./.dagger/modules/naming-app";
/// The source of naming-app in the commit's tree, beside the renderer's fixtures of it.
const NAMING_APP_SOURCE: &str =
    "crates/dagger-codegen/tests/fixtures/module_clients/naming-app.dang";
/// The one dependency of a module whose only client is the greeter, as generation writes
/// it in the module's `dagger-module.toml`.
const GREETER_DEPENDENCY: &str = "[[dependencies]]\nname = \"greeter\"\nsource = \"../greeter\"\n";
/// The manifest of an existing crate that `dagger module init` adopts, with a dependency
/// of its own.
const EXISTING_MANIFEST: &str = "[package]\nname = \"existing\"\nversion = \"0.1.0\"\n\
    edition = \"2024\"\nrust-version = \"1.99.1\"\n\n[dependencies]\nserde = \"1\"\n";
/// A toolchain file naming a Rust release older than the SDK's minimum.
const OLD_TOOLCHAIN: &str = "[toolchain]\nchannel = \"1.96.0\"\nprofile = \"minimal\"\n";
/// The password in a dependency URL that `dagger module init` must refuse without printing.
const CREDENTIAL: &str = "rust-sdk-secret-should-not-render";
/// The crates a release publishes, in the order it publishes them: the SDK depends on the
/// macros crate at the same version.
const PUBLISHED: [&str; 2] = ["tokeira-dagger-sdk-macros", "tokeira-dagger-sdk"];
/// The largest archive crates.io accepts.
const ARCHIVE_LIMIT: i64 = 10 * 1024 * 1024;
/// How Cargo names crates.io as a package's source.
const CRATES_IO: &str = "registry+https://github.com/rust-lang/crates.io-index";

#[dagger_sdk::object(root, rename = "Ci")]
pub struct Ci {
    #[dagger(state)]
    source: Directory,
}

#[dagger_sdk::methods]
impl Ci {
    #[dagger(constructor, rename = "ci")]
    pub fn new(
        #[dagger(
            doc = "Repository checkout; defaults to the workspace root.",
            default_path = "/",
            ignore = [".git", ".claude", "**/target"]
        )]
        source: Directory,
    ) -> Ci {
        Ci { source }
    }

    /// Runs the engine-free acceptance of docs/maintaining.md, section 5: the Cargo gates
    /// and the Go tests, concurrently.
    #[dagger(function)]
    pub async fn gates(
        &self,
        #[dagger(context)] context: ModuleContext,
    ) -> Result<String, ModuleError> {
        let dag = context.query();
        let cargo = cargo_gates(dag, &self.source).await?;
        let go = go_gates(dag, &self.source);
        tokio::try_join!(cargo.sync(), go.sync()).map_err(step_failure)?;
        Ok(GATES_PASSED.to_owned())
    }

    /// Runs the stock-engine acceptance of docs/engine-integration.md for a pushed commit:
    /// the runtime installed from it, a module initialized, given another module as its
    /// dependency with `dagger module client add`, regenerated, loaded and called, its calls
    /// to that module, a module that depends on it, collections, plain clients, a Cargo
    /// package that calls two modules through generated clients, an existing crate adopted,
    /// the refusals of broken modules and unsafe initializations,
    /// a legacy module, the README module's test and build, a plain client's query through a
    /// lost keepalive reply, and the later-engine step. It needs an engine of the release the
    /// commit targets.
    #[dagger(function)]
    pub async fn acceptance(
        &self,
        #[dagger(context)] context: ModuleContext,
        #[dagger(doc = "Full hash of a commit pushed to github.com/tokeira/dagger-rust-sdk.")]
        commit: String,
    ) -> Result<String, ModuleError> {
        let dag = context.query();
        let (tree, engine) = pushed(dag, &commit).await?;
        // The line `dagger module init` must write into the module's Cargo.toml: a runtime
        // installed from a commit has the modules it initializes depend on that commit.
        let dependency = format!(
            "dagger-sdk = {{ package = \"tokeira-dagger-sdk\", git = \"https://{REPOSITORY}\", rev = \"{commit}\" }}"
        );

        let cli = dagger_cli(dag).await?;
        // From the checkout: the module's own loaded source would regenerate it, which fails
        // when the committed generated files come from an engine of another platform.
        let fixtures = self.source.directory(".dagger/modules/ci/acceptance");
        let runtime = format!("{REPOSITORY}/runtime@{commit}");
        let later = later_passed();
        tokio::try_join!(
            module_flows(&cli, &fixtures, &runtime, &dependency),
            plain_clients(dag, &cli, &fixtures, &tree, &engine),
            package_clients(dag, &cli, &fixtures, &tree, &runtime, &dependency, &commit),
            adoption(&cli, &fixtures, &runtime, &dependency),
            load_refusals(&cli, &fixtures, &runtime),
            init_refusals(&cli, &fixtures, &runtime, &commit),
            legacy_module(&cli, &fixtures, &runtime),
            main_collection(&cli, &fixtures, &runtime),
            readme_module(&cli, &fixtures, &tree, &runtime),
            later_engine_step(dag, &cli, &fixtures, &tree, &runtime),
        )?;
        Ok(format!(
            "{commit} passed on {engine}: the runtime installed; a module initialized, got \
             another module as its dependency through dagger module client add, regenerated, \
             loaded and answered calls, Core enums, \
             scalars and defaults included, and its agent was listed and composed; it \
             constructed its dependency and called it, kept the dependency's object and \
             enum in private state between calls, and answered a module that depends on \
             it; its \
             collections answered the engine's operations, kept their bases and had their \
             items selected by a check, as did a module whose main object is an enum-keyed collection; plain clients \
             made each kind of Core call, \
             met each kind of failure and exported an image; a Cargo package got a client \
             of a module in its workspace and one of a module at the commit, ran both, and \
             kept the name of a type with an acronym; updating its client changed nothing, \
             a deleted generated file was restored, a removed client's files were pruned \
             and an edited generated file was refused; an \
             existing crate was adopted and one without a root object refused; modules with \
             missing or stale generated files, too old a toolchain, a misshapen agent or \
             a function that takes its dependency's object \
             failed to load, and one that declares an earlier release's engineVersion failed \
             to regenerate; \
             initialization wrote nothing outside the workspace and refused to overwrite a file \
             or print a credential; a legacy module answered a call; the README module's test, \
             build and recorded review passed, and its reviewer was listed and composed; \
             a plain client's query outlasted a lost reply to a \
             keepalive probe; and in the later-engine step, {later}"
        ))
    }

    /// Runs the later-engine step for a pushed commit. The engine of the release the commit
    /// targets runs as a service of the one that runs this module, and reports a later
    /// release while it serves the target's API view. On it, a module initialized with the
    /// runtime installed from the commit declares the target release, regenerates without
    /// changes, and answers calls, a collection query and a check; a module that declares
    /// the later release is refused with the engineVersion to declare instead; and a plain
    /// client built from the commit accepts the engine. `acceptance` runs the step too. It
    /// needs an engine of the release the commit targets.
    #[dagger(function)]
    pub async fn later_engine(
        &self,
        #[dagger(context)] context: ModuleContext,
        #[dagger(doc = "Full hash of a commit pushed to github.com/tokeira/dagger-rust-sdk.")]
        commit: String,
    ) -> Result<String, ModuleError> {
        let dag = context.query();
        let (tree, _) = pushed(dag, &commit).await?;
        let cli = dagger_cli(dag).await?;
        let fixtures = self.source.directory(".dagger/modules/ci/acceptance");
        let runtime = format!("{REPOSITORY}/runtime@{commit}");
        later_engine_step(dag, &cli, &fixtures, &tree, &runtime).await?;
        Ok(format!(
            "{commit} passed the later-engine step: {}",
            later_passed()
        ))
    }

    /// Packages the crates a release publishes, from a pushed commit, as `cargo publish`
    /// will: one `cargo package` verifies each crate by building it from its archive. An
    /// application outside the repository then builds and runs against the archives.
    /// Returns the archives, their SHA256SUMS, and each crate's file list to review before
    /// publishing. It needs an engine of the release the commit targets.
    #[dagger(function)]
    pub async fn package(
        &self,
        #[dagger(context)] context: ModuleContext,
        #[dagger(
            doc = "Full hash of the release commit, pushed to github.com/tokeira/dagger-rust-sdk."
        )]
        commit: String,
    ) -> Result<Directory, ModuleError> {
        let dag = context.query();
        let (tree, engine) = pushed(dag, &commit).await?;
        let version = release_version(dag, &tree).await?;
        unpublished(dag, &version).await?;
        let release = archives(dag, &tree, &commit, &version).await?;
        consumer(dag, &self.source, &engine, &version, Some(&release)).await?;
        Ok(release)
    }

    /// Proves a release on crates.io: each archive crates.io serves is the one `package`
    /// returned, and an application that depends on the version alone resolves exactly the
    /// published crates from crates.io, builds, and runs. It needs an engine of the release
    /// the version targets.
    #[dagger(function)]
    pub async fn published(
        &self,
        #[dagger(context)] context: ModuleContext,
        #[dagger(doc = "The SHA256SUMS file that `package` returned for the release.")] sums: File,
    ) -> Result<String, ModuleError> {
        let dag = context.query();
        let sums = sums.contents().await?;
        let ReleaseSums { version, archives } = release_sums(&sums)?;
        for (name, sha256) in &archives {
            // The engine refuses a download whose digest differs.
            dag.http_opts(
                format!("https://static.crates.io/crates/{name}/{name}-{version}.crate"),
                &QueryHttpOpts::default().with_checksum(format!("sha256:{sha256}")),
            )
            .size()
            .await
            .map_err(|error| {
                ModuleError::new(format!(
                    "crates.io does not serve the packaged {name} {version}: {}",
                    ModuleError::from(error).message()
                ))
            })?;
        }
        let engine = dag.version().await?;
        consumer(dag, &self.source, &engine, &version, None).await?;
        Ok(format!(
            "{version} is on crates.io as packaged: both archives match SHA256SUMS, and an \
             application that depends on tokeira-dagger-sdk {version} alone resolved both crates \
             from crates.io, built, and ran on {engine}"
        ))
    }
}

/// The tree of a commit pushed to the repository, with its `.git` directory, once the
/// commit is checked to target the engine that runs this module; and that engine's version.
async fn pushed(dag: &Query, commit: &str) -> Result<(Directory, String), ModuleError> {
    if commit.len() != 40
        || !commit
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(ModuleError::new(format!(
            "{commit:?} is not a full lowercase commit hash"
        )));
    }
    let tree = dag
        .git(format!("https://{REPOSITORY}"))
        .commit(commit)
        .tree();
    // The engine's error for a commit it cannot fetch does not name the usual cause.
    tree.sync().await.map_err(|error| {
        let cause = ModuleError::from(error);
        ModuleError::new(format!(
            "cannot fetch {commit} from https://{REPOSITORY}; push it first: {}",
            cause.message()
        ))
    })?;
    let target = json_file(&tree, "codegen/target.json").await?;
    let engine_version = string_field(&target, "codegen/target.json", "engine_version")?;
    let revision = string_field(&target, "codegen/target.json", "dagger_revision")?;
    if engine_version != format!("v{DAGGER_VERSION}") {
        return Err(ModuleError::new(format!(
            "{commit} targets {engine_version}, but this module drives v{DAGGER_VERSION}"
        )));
    }
    let expected = format!("{engine_version}+{}", revision.get(..8).unwrap_or(revision));
    let engine = dag.version().await?;
    if engine != expected {
        return Err(ModuleError::new(format!(
            "{commit} needs a {expected} engine; this one is {engine}"
        )));
    }
    Ok((tree, engine))
}

/// The Cargo half of the gates, in one container so the steps share their build output.
async fn cargo_gates(dag: &Query, source: &Directory) -> Result<Container, ModuleError> {
    let (triple, sha256) = match dag.default_platform().await?.as_str() {
        "linux/amd64" => (
            "x86_64-unknown-linux-musl",
            "f1f8eedc2a3ac297c540873f93785d4104b102c0079506b2a6b3221b7ec956af",
        ),
        "linux/arm64" => (
            "aarch64-unknown-linux-musl",
            "32580dcc2bc13fbeeb7c50edc38ef99c3b9ce9569a1d07a96e11b3b941f3e72e",
        ),
        other => {
            return Err(ModuleError::new(format!(
                "no pinned cargo-deny for {other}"
            )));
        }
    };
    let archive = format!("cargo-deny-{CARGO_DENY_VERSION}-{triple}");
    let binary = format!("{archive}/cargo-deny");
    // The engine verifies the digest before the archive reaches the container.
    let deny = dag.http_opts(
        format!(
            "https://github.com/EmbarkStudios/cargo-deny/releases/download/{CARGO_DENY_VERSION}/{archive}.tar.gz"
        ),
        &QueryHttpOpts::default().with_checksum(format!("sha256:{sha256}")),
    );
    let registry = dag.cache_volume("cargo-registry");
    let target = dag.cache_volume("ci-cargo-target");
    Ok(dag
        .container()
        .from(RUST_IMAGE)
        .with_exec(vec!["rustup", "component", "add", "clippy", "rustfmt"])
        .with_mounted_file("/tmp/cargo-deny.tar.gz", deny)
        .with_exec(vec![
            "tar",
            "-xzf",
            "/tmp/cargo-deny.tar.gz",
            "-C",
            "/usr/local/bin",
            "--strip-components=1",
            binary.as_str(),
        ])
        .with_mounted_cache(registry, "/usr/local/cargo/registry")
        .with_mounted_cache(target, "/cargo-target")
        .with_env_variable("CARGO_TARGET_DIR", "/cargo-target")
        .with_mounted_directory("/src", source.clone())
        .with_workdir("/src")
        .with_exec(vec!["cargo", "fmt", "--all", "--check"])
        .with_exec(vec![
            "cargo",
            "check",
            "--workspace",
            "--all-features",
            "--locked",
        ])
        .with_exec(vec![
            "cargo",
            "clippy",
            "--workspace",
            "--all-targets",
            "--all-features",
            "--locked",
            "--",
            "-D",
            "warnings",
        ])
        // Warnings fail documentation only; doctests keep the ordinary flags.
        .with_env_variable("RUSTDOCFLAGS", "-D warnings")
        .with_exec(vec![
            "cargo",
            "doc",
            "--workspace",
            "--all-features",
            "--no-deps",
            "--locked",
        ])
        .without_env_variable("RUSTDOCFLAGS")
        .with_exec(vec![
            "cargo",
            "test",
            "--workspace",
            "--all-features",
            "--locked",
            "--no-fail-fast",
        ])
        .with_exec(vec![
            "cargo",
            "test",
            "-p",
            "tokeira-dagger-sdk",
            "--no-default-features",
            "--locked",
            "--no-fail-fast",
        ])
        .with_exec(vec!["cargo", "deny", "check"])
        .with_exec(vec![
            "cargo",
            "run",
            "-p",
            "dagger-bootstrap",
            "--bin",
            "dagger-rust",
            "--locked",
            "--",
            "generate",
            "--workspace",
            ".",
            "--check",
        ]))
}

/// The Go half: the runtime's adapter.
fn go_gates(dag: &Query, source: &Directory) -> Container {
    dag.container()
        .from(GO_IMAGE)
        .with_mounted_cache(dag.cache_volume("ci-go-modules"), "/go/pkg/mod")
        .with_mounted_cache(dag.cache_volume("ci-go-build"), "/root/.cache/go-build")
        .with_mounted_directory("/src", source.clone())
        .with_workdir("/src/runtime")
        .with_exec(vec!["go", "vet", "./..."])
        .with_exec(vec!["go", "test", "-count=1", "./internal/metadata"])
        // The generated bindings read the session when the package loads; nothing connects.
        .with_env_variable("DAGGER_SESSION_PORT", "1")
        .with_env_variable("DAGGER_SESSION_TOKEN", "placeholder")
        .with_exec(vec!["go", "test", "-count=1", "."])
}

/// A Rust container with the target release's CLI, for the `dagger` commands that the
/// acceptance runs as new sessions of this engine.
async fn dagger_cli(dag: &Query) -> Result<Container, ModuleError> {
    let (platform, sha256) = match dag.default_platform().await?.as_str() {
        "linux/amd64" => (
            "linux_amd64",
            "de2a3ca569c3a955d5ce98d2c4879b67a4459c394a7e1684261ba7152bdb6865",
        ),
        "linux/arm64" => (
            "linux_arm64",
            "1ef003a4522d4f39c862d6dd360bc2916a605f87aad3dce4988c01f4bcd73358",
        ),
        other => {
            return Err(ModuleError::new(format!(
                "no pinned Dagger CLI for {other}"
            )));
        }
    };
    let archive = dag.http_opts(
        format!(
            "https://dl.dagger.io/dagger/releases/{DAGGER_VERSION}/dagger_v{DAGGER_VERSION}_{platform}.tar.gz"
        ),
        &QueryHttpOpts::default().with_checksum(format!("sha256:{sha256}")),
    );
    Ok(dag
        .container()
        .from(RUST_IMAGE)
        .with_mounted_file("/tmp/dagger.tar.gz", archive)
        .with_exec(vec![
            "tar",
            "-xzf",
            "/tmp/dagger.tar.gz",
            "-C",
            "/usr/local/bin",
            "dagger",
        ])
        .with_env_variable("DAGGER_NO_NAG", "1")
        .with_env_variable("GIT_AUTHOR_NAME", "acceptance")
        .with_env_variable("GIT_AUTHOR_EMAIL", "acceptance@example.invalid")
        .with_env_variable("GIT_COMMITTER_NAME", "acceptance")
        .with_env_variable("GIT_COMMITTER_EMAIL", "acceptance@example.invalid"))
}

/// Steps 1 to 5 of the acceptance: install the runtime, initialize a module, load it before
/// regeneration, give it another module as its dependency with `dagger module client add`,
/// regenerate it twice, call its exports, among them the ones that call its dependency, and
/// call it from a module that depends on it.
async fn module_flows(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
    dependency: &str,
) -> Result<(), ModuleError> {
    let workspace = dagger(
        &installed(cli, "/ws", runtime),
        &["-y", "module", "init", "rust", "--name", "gate"],
    );
    let manifest = workspace
        .file("/ws/.dagger/modules/gate/Cargo.toml")
        .contents()
        .await
        .map_err(step_failure)?;
    if !manifest.lines().any(|line| line == dependency) {
        return Err(check_failed(
            "dagger module init",
            format!("the module's Cargo.toml lacks `{dependency}`:\n{manifest}"),
        ));
    }
    let workspace = commit_all(&workspace, "initialize gate module")
        .with_file(
            "/ws/.dagger/modules/gate/src/lib.rs",
            fixtures.file("gate.rs"),
        )
        .with_new_file("rust module gate\n", "/ws/gate-input/note.txt")
        // The greeter's default directory leaves Markdown files out.
        .with_new_file(
            "left out of the greeter's default directory\n",
            "/ws/notes.md",
        );
    let workspace = with_caller(&workspace, fixtures, "/ws", "gate");
    // The authored source is newer than the generated files until the client is added,
    // which regenerates the module.
    let note = ["call", "gate", "note", "--source", "gate-input", "contents"];
    refused(&workspace, &note, "run `dagger generate`").await?;

    let workspace = with_greeter(Via::NewSession, &workspace, fixtures, "/ws", "gate").await?;
    let workspace = commit_all(
        &dagger(&workspace, &["generate", "-y"]),
        "regenerate gate module",
    );
    let workspace = dagger(&workspace, &["generate", "-y"]);
    unchanged(&workspace, "a second dagger generate").await?;
    // The engine generates the module against a schema that holds its dependency's types.
    let binding = workspace
        .file("/ws/.dagger/modules/gate/src/dagger_generated/greeter.rs")
        .contents()
        .await
        .map_err(|error| {
            check_failed(
                "dagger generate",
                format!("wrote no binding for the dependency's type Greeter: {error}"),
            )
        })?;
    if !binding.contains("pub struct Greeter") {
        return Err(check_failed(
            "dagger generate",
            format!("the binding for the dependency lacks its type Greeter:\n{binding}"),
        ));
    }
    let attributes = workspace
        .file("/ws/.dagger/modules/gate/.gitattributes")
        .contents()
        .await
        .map_err(step_failure)?;
    if attributes.contains("/.dagger/modules/gate/") {
        return Err(check_failed(
            "dagger generate",
            format!("the module's .gitattributes names paths outside it:\n{attributes}"),
        ));
    }
    tokio::try_join!(
        prints(&workspace, &note, "rust module gate"),
        prints(
            &workspace,
            &["call", "gate", "count", "--source", "gate-input"],
            "1"
        ),
        described(&workspace, ".dagger/modules/gate", GATE_DESCRIPTION),
    )?;
    // A Core enum or scalar crosses the boundary as the engine's string, and a default
    // applies when the call omits its argument.
    tokio::try_join!(
        prints(&workspace, &["call", "gate", "flip"], "TCP"),
        prints(
            &workspace,
            &["call", "gate", "flip", "--protocol", "TCP"],
            "UDP"
        ),
        prints(&workspace, &["call", "gate", "platform"], "linux/arm64"),
        prints(&workspace, &["call", "gate", "labels"], "{\"gate\":true}"),
        prints(
            &workspace,
            &["call", "gate", "labels", "--labels", "{\"a\":[1,2]}"],
            "{\"a\":[1,2]}"
        ),
        prints(
            &workspace,
            &["agent", "--list", "--format", "link"],
            "dag+expertise://?expertise=gate/expert"
        ),
        composed(&workspace, &["flip"], &["expert"]),
    )?;
    dependency_calls(&workspace).await?;
    collections(&workspace).await
}

/// Step 5: the gate module constructs the greeter, the Dang module it depends on, with and
/// without the constructor's optional argument, and calls it through its generated
/// bindings: a function with and without its optional argument, one that returns an object
/// of the greeter's with fields, one that takes that object as the greeter's interface and
/// returns the interface, one that takes and returns the greeter's enum, one that takes and
/// returns a Core object, and one whose directory the engine fills in. It loads the
/// greeter's object from its ID, and its own object keeps a greeter and the greeter's enum
/// in private state from one call to the next. A Dang module that depends on the gate
/// module calls it in turn.
async fn dependency_calls(workspace: &Container) -> Result<(), ModuleError> {
    tokio::try_join!(
        prints(
            workspace,
            &["call", "gate", "greet", "--name", "gate"],
            "hello, gate"
        ),
        prints(
            workspace,
            &[
                "call",
                "gate",
                "salute",
                "--name",
                "gate",
                "--greeting",
                "hi",
                "--ending",
                "!"
            ],
            "hi, gate!"
        ),
        prints(
            workspace,
            &["call", "gate", "message", "--name", "gate"],
            "gate\nhello, gate"
        ),
        prints(
            workspace,
            &["call", "gate", "named", "--name", "gate"],
            "gate\ngate"
        ),
        prints(
            workspace,
            &["call", "gate", "reloaded", "--name", "gate"],
            "hello, gate\nhello, gate"
        ),
        prints(workspace, &["call", "gate", "restyle"], "LOUD\nPLAIN"),
        prints(
            workspace,
            &[
                "call",
                "gate",
                "stamped",
                "--source",
                "gate-input",
                "file",
                "--path",
                "greeting.txt",
                "contents"
            ],
            "hello"
        ),
        default_directory_listed(workspace),
        // Each call after `welcome` decodes the state that the call before it returned.
        prints(
            workspace,
            &[
                "call",
                "gate",
                "welcome",
                "--greeting",
                "hi",
                "greet",
                "--name",
                "gate"
            ],
            "hi, gate"
        ),
        prints(
            workspace,
            &[
                "call",
                "gate",
                "welcome",
                "--greeting",
                "hi",
                "restyled",
                "greet",
                "--name",
                "gate"
            ],
            "HI, GATE"
        ),
        prints(
            workspace,
            &[
                "-m",
                ".dagger/modules/caller",
                "call",
                "relay",
                "--name",
                "gate"
            ],
            "hello, gate"
        ),
    )?;
    Ok(())
}

/// The greeter lists the directory that the engine gives it when a call passes none: the
/// workspace's root, without its Markdown files.
async fn default_directory_listed(workspace: &Container) -> Result<(), ModuleError> {
    let args = ["call", "gate", "listed"];
    let output = dagger(workspace, &args)
        .stdout()
        .await
        .map_err(step_failure)?;
    let entries: Vec<&str> = output.lines().collect();
    if entries.contains(&"gate-input/") && !entries.contains(&"notes.md") {
        Ok(())
    } else {
        Err(check_failed(
            &format!("dagger {}", args.join(" ")),
            format!("listed {entries:?}, not the workspace's root without notes.md"),
        ))
    }
}

/// Step 5: the gate module's collection answers the engine's `keys`, `list`, `get` and
/// `subset`, and the engine computes its delta against the base that derived values keep,
/// as upstream's collection tests check with a Go module. Upstream passes a collection
/// back as an argument through a self-call, which a Rust module cannot make, so its ID
/// goes to a second query instead.
async fn collections(workspace: &Container) -> Result<(), ModuleError> {
    let id = async {
        let response = query(workspace, "{ gate { items { id } } }").await?;
        response["gate"]["items"]["id"]
            .as_str()
            .map(str::to_owned)
            .ok_or_else(|| check_failed("the items' ID", format!("is missing from {response}")))
    };
    let (_, _, _, _, _, _, id) = tokio::try_join!(
        prints(workspace, &["call", "gate", "items", "keys"], "b\na\nc"),
        listed_items(workspace),
        queried(workspace, COLLECTION_QUERY, COLLECTION_EXPECTED),
        queried(workspace, COLLECTION_DELTA_QUERY, COLLECTION_DELTA_EXPECTED),
        queried(
            workspace,
            "{ gate { items { change(names: [\"c\", \"d\"]) { deltaCheck { pass } } } } }",
            r#"{"gate":{"items":{"change":{"deltaCheck":{"pass":true}}}}}"#,
        ),
        selected_checks(workspace),
        id,
    )?;
    queried(
        workspace,
        &format!("{{ gate {{ forward(items: {id:?}) {{ keys added }} }} }}"),
        r#"{"gate":{"forward":{"keys":["d"],"added":["d"]}}}"#,
    )
    .await
}

/// The query of upstream's `TestGoAPI`, less its self-calls, and its answer.
const COLLECTION_QUERY: &str = r#"{ gate { items {
  keys
  list { name }
  get(key: "a") { name }
  selected removed
  subset(keys: ["c", "b"]) {
    keys
    selected removed copy { subset(keys: ["c"]) { removed } }
    subset(keys: ["c"]) { keys selected removed }
    empty: subset(keys: []) { keys list { name } selected removed }
  }
} } }"#;
const COLLECTION_EXPECTED: &str = r#"{"gate":{"items":{
  "keys":["b","a","c"],
  "list":[{"name":"item:b"},{"name":"item:a"},{"name":"item:c"}],
  "get":{"name":"item:a"},
  "subset":{
    "keys":["b","c"],
    "subset":{"keys":["c"],"selected":["c"],"removed":["b","a"]},
    "empty":{"keys":[],"list":[],"selected":[],"removed":["b","a","c"]},
    "selected":["b","c"],
    "removed":["a"],
    "copy":{"subset":{"removed":["b","a"]}}
  },
  "selected":["b","a","c"],
  "removed":[]
}}}"#;

/// The delta query of upstream's `TestGoAPI`, and its answer.
const COLLECTION_DELTA_QUERY: &str = r#"{ gate { items {
  change(names: ["c", "d"]) {
    keys
    added removed change(names: ["c", "b", "a"]) { added removed }
    subset(keys: ["d"]) { added removed }
  }
  subset(keys: ["c"]) {
    change(names: ["b", "c", "d"]) { added removed }
    fresh { keys added removed }
  }
} } }"#;
const COLLECTION_DELTA_EXPECTED: &str = r#"{"gate":{"items":{
  "subset":{"change":{"added":["d"],"removed":["a"]},"fresh":{"keys":["z"],"added":[],"removed":[]}},
  "change":{
    "keys":["c","d"],
    "subset":{"added":["d"],"removed":["b","a","c"]},
    "added":["d"],
    "removed":["b","a"],
    "change":{"added":[],"removed":[]}
  }
}}}"#;

/// `dagger call` lists one item for each key, as upstream's `TestCallProjectedList` checks.
async fn listed_items(workspace: &Container) -> Result<(), ModuleError> {
    let args = ["call", "gate", "items", "list"];
    let output = dagger(workspace, &args)
        .stdout()
        .await
        .map_err(step_failure)?;
    if output.matches("Item@").count() == 3 {
        Ok(())
    } else {
        Err(check_failed(
            &format!("dagger {}", args.join(" ")),
            format!("printed {output:?}, not three items"),
        ))
    }
}

/// `dagger check` runs an item's check once for each item, and the collection's item flag
/// selects which, as upstream's `TestCheckSelection` checks: run alone, item c fails, and
/// with the flag selecting items a and b, it never runs.
async fn selected_checks(workspace: &Container) -> Result<(), ModuleError> {
    let listing = ["check", "-l", "--all", "-f=cli", "gate/items/verify"];
    let output = dagger(workspace, &listing)
        .stdout()
        .await
        .map_err(step_failure)?;
    let check = format!("dagger {}", listing.join(" "));
    // Each row selects one item with `--<module> --<item flag>=<key>`, followed by the
    // check's description as a `#` comment.
    let mut selectors: Vec<(&str, &str)> = output
        .lines()
        .filter(|line| !line.starts_with('#'))
        .filter_map(|line| {
            let selection = line
                .split_once('#')
                .map_or(line, |(selection, _)| selection);
            selection.split_whitespace().last()?.split_once('=')
        })
        .collect();
    selectors.sort_by_key(|(_, key)| *key);
    let flag = match selectors.as_slice() {
        [(flag, "a"), (b, "b"), (c, "c")] if flag == b && flag == c => *flag,
        _ => {
            return Err(check_failed(
                &check,
                format!("printed {output:?}, not one row for each of a, b and c"),
            ));
        }
    };
    let selected = [
        "check".to_owned(),
        "gate/items/verify".to_owned(),
        format!("{flag}=a"),
        format!("{flag}=b"),
    ];
    let selected: Vec<&str> = selected.iter().map(String::as_str).collect();
    let (run, _) = tokio::try_join!(
        async {
            dagger(workspace, &selected)
                .combined_output()
                .await
                .map_err(step_failure)
        },
        refused(
            workspace,
            &["check", "gate/items/verify"],
            "unselected item c ran"
        ),
    )?;
    if run.contains("unselected item c ran") {
        return Err(check_failed(
            &format!("dagger {}", selected.join(" ")),
            format!("ran item c:\n{}", tail(&run)),
        ));
    }
    Ok(())
}

/// Step 5: a module whose main object is a collection, keyed by an enum and with members of
/// the default names, answers the engine's collection operations, as upstream's
/// `TestMainCollection` and `TestEnumKeys` check. The query names the enum's members as the
/// engine spells them, so the variant `Red` is `RED`.
async fn main_collection(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
) -> Result<(), ModuleError> {
    let workspace = commit_all(
        &initialized(cli, "shelf", runtime).with_file(
            "/shelf/.dagger/modules/shelf/src/lib.rs",
            fixtures.file("shelf.rs"),
        ),
        "shelf module",
    );
    let workspace = dagger(&workspace, &["generate", "-y"]);
    queried(
        &workspace,
        "{ shelf { keys get(key: RED) { name } subset(keys: [BLUE]) { keys count removed get(key: BLUE) { name } } } }",
        r#"{"shelf":{"keys":["RED","BLUE"],"get":{"name":"red"},"subset":{"keys":["BLUE"],"count":1,"removed":["RED"],"get":{"name":"blue"}}}}"#,
    )
    .await
}

/// Sends `document` with `dagger api query`, which serves the workspace's modules, and
/// returns the response.
async fn query(container: &Container, document: &str) -> Result<Value, ModuleError> {
    query_via(Via::NewSession, container, document).await
}

/// `query`, with `dagger` reaching its engine `via`.
async fn query_via(via: Via, container: &Container, document: &str) -> Result<Value, ModuleError> {
    let output = dagger_via(
        via,
        &container.with_new_file(document, "/query.graphql"),
        &["api", "query", "--doc", "/query.graphql"],
    )
    .stdout()
    .await
    .map_err(step_failure)?;
    serde_json::from_str(&output).map_err(|error| {
        check_failed(
            &format!("the query {document:?}"),
            format!("printed no JSON: {error}\n{}", tail(&output)),
        )
    })
}

/// Checks that `document` answers `expected`, a JSON document.
async fn queried(container: &Container, document: &str, expected: &str) -> Result<(), ModuleError> {
    queried_via(Via::NewSession, container, document, expected).await
}

/// `queried`, with `dagger` reaching its engine `via`.
async fn queried_via(
    via: Via,
    container: &Container,
    document: &str,
    expected: &str,
) -> Result<(), ModuleError> {
    let expected: Value = serde_json::from_str(expected)
        .map_err(|error| check_failed("the expected answer", format!("is not JSON: {error}")))?;
    let response = query_via(via, container, document).await?;
    if response == expected {
        Ok(())
    } else {
        Err(check_failed(
            &format!("the query {document:?}"),
            format!("answered {response}, not {expected}"),
        ))
    }
}

/// Step 7: a Cargo package that is not a module calls two modules through clients that
/// `dagger module client add` generates into it: naming-app, a Dang module in its workspace
/// with an acronym in a type's name, and the greeter, loaded from the repository at the
/// commit. The package's program runs against the engine with both. Then updating the
/// greeter's client changes nothing, generation restores a deleted file, removing
/// naming-app's client prunes its files, and generation refuses to overwrite an edited
/// file. A repository of its own, since it syncs other contents than the modules' flows.
async fn package_clients(
    dag: &Query,
    cli: &Container,
    fixtures: &Directory,
    tree: &Directory,
    runtime: &str,
    dependency: &str,
    commit: &str,
) -> Result<(), ModuleError> {
    let root = "/clients";
    let app = "/clients/app";
    let clients = "/clients/app/src/dagger_clients";
    let greeter = format!("{REPOSITORY}/.dagger/modules/ci/acceptance/greeter@{commit}");
    let cli = cli
        .with_mounted_cache(
            dag.cache_volume("cargo-registry"),
            "/usr/local/cargo/registry",
        )
        // The package depends on the SDK at the commit, which Cargo fetches from the
        // repository.
        .with_mounted_cache(dag.cache_volume("cargo-git"), "/usr/local/cargo/git")
        // Outside the workspace, which holds only what the author commits.
        .with_env_variable("CARGO_TARGET_DIR", "/app-target");
    let package = commit_all(
        &installed(&cli, root, runtime)
            .with_new_file(
                dang_manifest("naming-app"),
                "/clients/.dagger/modules/naming-app/dagger-module.toml",
            )
            .with_file(
                "/clients/.dagger/modules/naming-app/main.dang",
                tree.file(NAMING_APP_SOURCE),
            )
            .with_new_file(APP_MANIFEST, "/clients/app/Cargo.toml")
            .with_new_file("fn main() {}\n", "/clients/app/src/main.rs"),
        "application and a module beside it",
    )
    .with_workdir(app);

    let add_local = [
        "module",
        "client",
        "add",
        "-y",
        "../.dagger/modules/naming-app",
    ];
    let add_git = ["module", "client", "add", "-y", greeter.as_str()];
    let added = dagger(&dagger(&package, &add_local), &add_git);
    let check = "dagger module client add in a Cargo package";
    let (mut entries, manifest, config, fetcher) = tokio::try_join!(
        directory_entries(&added, clients),
        file_contents(&added, "/clients/app/Cargo.toml"),
        file_contents(&added, "/clients/dagger.toml"),
        file_contents(
            &added,
            format!("{clients}/naming_app/naming_app_http_fetcher.rs")
        ),
    )?;
    entries.sort();
    if entries
        != [
            ".dagger-generated.json",
            "greeter/",
            "mod.rs",
            "naming_app/",
        ]
    {
        return Err(check_failed(
            check,
            format!(
                "src/dagger_clients holds {entries:?}, not a record, mod.rs and one directory \
                 for each client"
            ),
        ));
    }
    let expected = format!("{APP_MANIFEST}{dependency}\n");
    if manifest != expected {
        return Err(check_failed(
            check,
            format!("the package's Cargo.toml did not gain exactly `{dependency}`:\n{manifest}"),
        ));
    }
    let mut recorded = recorded_clients(&config, "app");
    recorded.sort();
    if recorded != [NAMING_APP, greeter.as_str()] {
        return Err(check_failed(
            check,
            format!(
                "dagger.toml records {recorded:?} for the scope app, not {NAMING_APP} and \
                 {greeter}:\n{config}"
            ),
        ));
    }
    // The engine serves the type under this name, which a client must send as it is.
    if !fetcher.contains("\"NamingAppHTTPFetcher\"") {
        return Err(check_failed(
            check,
            format!("naming-app's client does not name its type NamingAppHTTPFetcher:\n{fetcher}"),
        ));
    }

    // The author declares the clients' module and calls them. Generation edits neither.
    let authored = commit_all(
        &added
            .with_file("/clients/app/src/main.rs", fixtures.file("app.rs"))
            .with_exec(vec!["cargo", "generate-lockfile", "--quiet"]),
        "application that calls its clients",
    );
    let run = client_run(
        &authored.with_exec(vec!["cargo", "build", "--quiet", "--locked"]),
        "app",
        ContainerWithExecOpts::default(),
        APP_ANSWER,
    )
    .await?;

    // The client is pinned to a commit, which no later commit replaces.
    let updated = dagger(
        &run,
        &["module", "client", "update", "-y", greeter.as_str()],
    );
    unchanged(
        &updated,
        "dagger module client update of a client at a commit",
    )
    .await?;

    let style = format!("{clients}/greeter/greeter_style.rs");
    let restored = dagger(
        &updated
            .with_exec(vec!["rm", style.as_str()])
            .with_workdir(root),
        &["generate", "-y"],
    );
    // The committed file is the one generation wrote, so no change means the same bytes.
    unchanged(
        &restored,
        "dagger generate after a generated file was deleted",
    )
    .await?;

    let remove = ["module", "client", "rm", "-y", NAMING_APP];
    let removed = dagger(&restored.with_workdir(app), &remove);
    let check = format!("dagger {}", remove.join(" "));
    let (left, record, declared, config) = tokio::try_join!(
        directory_entries(&removed, format!("{clients}/naming_app")),
        file_contents(
            &removed,
            format!("{clients}/naming_app/.dagger-generated.json")
        ),
        file_contents(&removed, format!("{clients}/mod.rs")),
        file_contents(&removed, "/clients/dagger.toml"),
    )?;
    let record: Value = serde_json::from_str(&record).map_err(|error| {
        check_failed(&check, format!("left a record that is not JSON: {error}"))
    })?;
    if left != [".dagger-generated.json"] || record["files"] != serde_json::json!({}) {
        return Err(check_failed(
            &check,
            format!(
                "left {left:?} in src/dagger_clients/naming_app with the record {record}, not \
                 the emptied record alone"
            ),
        ));
    }
    if declared.contains("naming_app") || !declared.contains("pub mod greeter;") {
        return Err(check_failed(
            &check,
            format!("src/dagger_clients/mod.rs does not declare the greeter alone:\n{declared}"),
        ));
    }
    let recorded = recorded_clients(&config, "app");
    if recorded != [greeter.as_str()] {
        return Err(check_failed(
            &check,
            format!(
                "dagger.toml records {recorded:?} for the scope app, not {greeter} alone:\n{config}"
            ),
        ));
    }

    let generated = file_contents(&removed, style.as_str()).await?;
    let edited = commit_all(
        &removed
            .with_new_file(format!("{generated}// Edited by hand.\n"), style.as_str())
            .with_workdir(root),
        "client without naming-app, and an edited generated file",
    );
    let refusal = refused(
        &edited,
        &["generate", "-y"],
        "src/dagger_clients/greeter/greeter_style.rs contains user changes; refusing to \
         overwrite it",
    )
    .await?;
    unchanged(&refusal, "the refused generation over an edited file").await
}

/// The clients that the workspace configuration `config` records for the Rust SDK's scope
/// `scope`, as it writes them.
fn recorded_clients(config: &str, scope: &str) -> Vec<String> {
    let headers = [
        format!("[sdks.rust.scopes.{scope}]"),
        format!("[sdks.rust.scopes.\"{scope}\"]"),
    ];
    let table: Vec<&str> = config
        .lines()
        .skip_while(|line| !headers.iter().any(|header| line.trim() == header))
        .skip(1)
        .take_while(|line| !line.trim_start().starts_with('['))
        .collect();
    // An array of TOML's basic strings without escapes reads as JSON.
    table
        .join("\n")
        .split_once("clients = ")
        .and_then(|(_, list)| list.split_once(']'))
        .and_then(|(list, _)| serde_json::from_str(&format!("{list}]")).ok())
        .unwrap_or_default()
}

/// Steps 6 and 12: plain clients, built from the commit, run under `dagger run`. One makes
/// Void calls and exports an image; another makes each kind of generated Core call and meets
/// each kind of failure the client reports; the third keeps a query through a lost reply to
/// a keepalive probe.
async fn plain_clients(
    dag: &Query,
    cli: &Container,
    fixtures: &Directory,
    tree: &Directory,
    engine: &str,
) -> Result<(), ModuleError> {
    let client = client_project(dag, cli, fixtures, tree);
    let canary = async {
        let expected = format!("ACCEPTANCE-CLIENT-OK {engine}");
        let run = client_run(
            &client,
            "acceptance-client",
            ContainerWithExecOpts::default(),
            &expected,
        )
        .await?;
        let image = run
            .with_exec(vec!["tar", "-tf", "canary.tar"])
            .stdout()
            .await
            .map_err(step_failure)?;
        if image.lines().any(|line| line == "index.json") {
            Ok(())
        } else {
            Err(check_failed(
                "the plain client",
                format!("exported no OCI image:\n{image}"),
            ))
        }
    };
    let conformance = format!("ACCEPTANCE-CONFORMANCE-OK {engine}");
    let keepalive = format!("ACCEPTANCE-KEEPALIVE-OK {engine}");
    tokio::try_join!(
        canary,
        client_run(
            &client,
            "conformance",
            ContainerWithExecOpts::default(),
            &conformance
        ),
        // iptables needs the network administration capability.
        client_run(
            &client,
            "keepalive",
            ContainerWithExecOpts::default().with_insecure_root_capabilities(true),
            &keepalive
        ),
    )?;
    Ok(())
}

/// The acceptance's plain clients, in a Git repository at `/client`, built against the
/// commit's SDK at `/sdk`.
fn client_project(
    dag: &Query,
    cli: &Container,
    fixtures: &Directory,
    tree: &Directory,
) -> Container {
    let client = cli
        // For the keepalive client, which drops packets with iptables.
        .with_exec(vec!["apt-get", "update", "--quiet"])
        .with_exec(vec![
            "apt-get",
            "install",
            "--quiet",
            "--yes",
            "--no-install-recommends",
            "iptables",
        ])
        .with_mounted_cache(
            dag.cache_volume("cargo-registry"),
            "/usr/local/cargo/registry",
        )
        .with_directory("/sdk", tree.clone())
        .with_directory("/client", fixtures.directory("client"));
    // `Workspace.export` needs a Git workspace.
    repository(&client, "/client")
        .with_exec(vec!["cargo", "generate-lockfile", "--quiet"])
        .with_exec(vec!["cargo", "build", "--quiet", "--locked"])
}

/// Runs the client binary `bin` under `dagger run`, in an exec with `opts`, which must print
/// the line `expected`, and returns the container as the run left it.
async fn client_run(
    client: &Container,
    bin: &str,
    opts: ContainerWithExecOpts,
    expected: &str,
) -> Result<Container, ModuleError> {
    client_run_via(Via::NewSession, client, bin, opts, expected).await
}

/// `client_run`, with `dagger run` reaching its engine `via`.
async fn client_run_via(
    via: Via,
    client: &Container,
    bin: &str,
    opts: ContainerWithExecOpts,
    expected: &str,
) -> Result<Container, ModuleError> {
    let args = ["run", "cargo", "run", "--quiet", "--locked", "--bin", bin];
    let run = client.with_exec_opts(dagger_command(&args), &via.exec_opts(opts));
    let output = run.stdout().await.map_err(step_failure)?;
    if output.lines().any(|line| line == expected) {
        Ok(run)
    } else {
        Err(check_failed(
            &format!("dagger {}", args.join(" ")),
            format!("printed no `{expected}`:\n{}", tail(&output)),
        ))
    }
}

/// Step 8: `dagger module init` adopts an existing crate whose source declares a root object,
/// keeping its source and its own dependencies, and refuses one that declares none.
async fn adoption(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
    dependency: &str,
) -> Result<(), ModuleError> {
    let adopted = async {
        let source = fixtures.file("adopted.rs");
        let existing = commit_all(
            &installed(cli, "/adopt", runtime)
                .with_new_file(
                    EXISTING_MANIFEST,
                    "/adopt/.dagger/modules/existing/Cargo.toml",
                )
                .with_file("/adopt/.dagger/modules/existing/src/lib.rs", source.clone()),
            "existing crate",
        );
        let adopted = commit_all(
            &dagger(
                &existing,
                &["-y", "module", "init", "rust", "--name", "existing"],
            ),
            "adopt existing crate",
        );
        let kept = adopted.file("/adopt/.dagger/modules/existing/src/lib.rs");
        let manifest = adopted.file("/adopt/.dagger/modules/existing/Cargo.toml");
        let (kept, authored, manifest) =
            tokio::try_join!(kept.contents(), source.contents(), manifest.contents())
                .map_err(step_failure)?;
        if kept != authored {
            return Err(check_failed(
                "dagger module init",
                "changed the adopted crate's src/lib.rs",
            ));
        }
        for line in ["serde = \"1\"", dependency] {
            if !manifest.lines().any(|candidate| candidate == line) {
                return Err(check_failed(
                    "dagger module init",
                    format!("the adopted crate's Cargo.toml lacks `{line}`:\n{manifest}"),
                ));
            }
        }
        prints(&adopted, &["call", "existing", "adopted"], "adopted").await
    };

    let rootless = async {
        let rootless = commit_all(
            &installed(cli, "/rootless", runtime)
                .with_new_file(
                    crate_manifest("rootless"),
                    "/rootless/.dagger/modules/rootless/Cargo.toml",
                )
                .with_new_file(
                    "pub fn caller_owned() {}\n",
                    "/rootless/.dagger/modules/rootless/src/lib.rs",
                ),
            "crate without a root object",
        );
        let refusal = refused(
            &rootless,
            &["-y", "module", "init", "rust", "--name", "rootless"],
            "module.root-missing",
        )
        .await?;
        unchanged(&refusal, "the refused crate without a root object").await
    };

    tokio::try_join!(adopted, rootless)?;
    Ok(())
}

/// Step 9: a module whose generated files are missing, or which changed after its last
/// generation, fails to load; so does one whose toolchain is older than the SDK's minimum,
/// even once regenerated, one whose agent function does not return the conversation, and
/// one whose function takes an object of the module it depends on.
/// One that declares an earlier release as its engineVersion fails to regenerate, with a
/// message that names the engineVersion to declare.
async fn load_refusals(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
) -> Result<(), ModuleError> {
    let ungenerated = async {
        let module = initialized(cli, "ungenerated", runtime).with_exec(vec![
            "rm",
            ".dagger/modules/ungenerated/.dagger/rust/operation-manifest.json",
        ]);
        refused(&module, &["functions", "ungenerated"], "GENERATED_MISSING").await
    };

    // A dependency added without regenerating.
    let stale = async {
        let module = initialized(cli, "stale", runtime);
        let manifest = module
            .file("/stale/.dagger/modules/stale/Cargo.toml")
            .contents()
            .await
            .map_err(step_failure)?;
        let module = module.with_new_file(
            manifest.replacen("[dependencies]\n", "[dependencies]\nanyhow = \"1\"\n", 1),
            "/stale/.dagger/modules/stale/Cargo.toml",
        );
        refused(&module, &["functions", "stale"], "GENERATED_STALE").await
    };

    let toolchain = async {
        let module = dagger(
            &initialized(cli, "toolchain", runtime).with_new_file(
                OLD_TOOLCHAIN,
                "/toolchain/.dagger/modules/toolchain/rust-toolchain.toml",
            ),
            &["generate", "-y"],
        );
        refused(
            &module,
            &["functions", "toolchain"],
            "TOOLCHAIN_UNSUPPORTED",
        )
        .await
    };

    // The engine checks the shape of an agent function when it loads the module, as it
    // does for every SDK, and the author sees its reason.
    let agent = async {
        let module = dagger(
            &initialized(cli, "advisor", runtime).with_file(
                "/advisor/.dagger/modules/advisor/src/lib.rs",
                fixtures.file("advisor.rs"),
            ),
            &["generate", "-y"],
        );
        refused(
            &module,
            &["functions", "advisor"],
            "function \"expert\" is marked @agent but does not return LLM!",
        )
        .await
    };

    // The engine refuses a dependency's type in a module's own function when it loads the
    // module, as it does for every SDK, and the author sees its reason. Adding the client
    // regenerates the module: generation binds the type and accepts the function.
    let external = async {
        let module = initialized(cli, "lender", runtime).with_file(
            "/lender/.dagger/modules/lender/src/lib.rs",
            fixtures.file("lender.rs"),
        );
        let module = with_greeter(Via::NewSession, &module, fixtures, "/lender", "lender").await?;
        refused(
            &module,
            &["functions", "lender"],
            "arg \"greeter\" cannot reference external type from dependency module \"greeter\"",
        )
        .await
    };

    // A module made for an earlier release keeps that release's engineVersion, so the
    // engine serves it that release's API view, which generation refuses.
    let earlier = async {
        let module = initialized(cli, "earlier", runtime);
        let path = "/earlier/.dagger/modules/earlier/dagger-module.toml";
        let manifest =
            declares_target(&module, path, "dagger module init rust --name earlier").await?;
        let module = module.with_new_file(
            manifest.replacen(
                &target_declaration(),
                "engineVersion = \"v1.0.0-beta.21\"\n",
                1,
            ),
            path,
        );
        refused(
            &module,
            &["generate", "-y"],
            &format!(
                "this SDK requires the v{DAGGER_VERSION} view; a module selects its view with \
                 engineVersion"
            ),
        )
        .await
    };

    tokio::try_join!(ungenerated, stale, toolchain, agent, external, earlier)?;
    Ok(())
}

/// Step 10: `dagger module init` writes nothing outside the workspace: it refuses a path that
/// climbs out of it and a module path that is a symbolic link leading out. It also refuses to
/// overwrite a file it does not own or to depend on a URL that carries a credential, which it
/// does not print.
async fn init_refusals(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
    commit: &str,
) -> Result<(), ModuleError> {
    let escape = async {
        let refusal = refused(
            &installed(cli, "/escape", runtime),
            &[
                "-y",
                "module",
                "init",
                "rust",
                "--name",
                "escape",
                "--path",
                "../../rust-sdk-escape",
            ],
            "escapes workspace root",
        )
        .await?;
        unchanged(&refusal, "the refused path outside the workspace").await?;
        if refusal
            .exists("/rust-sdk-escape")
            .await
            .map_err(step_failure)?
        {
            return Err(check_failed(
                "the refused path outside the workspace",
                "wrote /rust-sdk-escape",
            ));
        }
        Ok(())
    };

    // The engine hands the runtime the link itself, which the runtime refuses to write
    // through.
    let symlink = async {
        let linked = commit_all(
            &installed(cli, "/symlink", runtime)
                .with_exec(vec!["mkdir", "-p", "/outside", ".dagger/modules"])
                .with_exec(vec!["ln", "-s", "/outside", ".dagger/modules/symlink"]),
            "module path that links outside the workspace",
        );
        let refusal = refused(
            &linked,
            &[
                "-y",
                "module",
                "init",
                "rust",
                "--name",
                "symlink",
                "--path",
                ".dagger/modules/symlink",
            ],
            "OUTPUT_SYMLINK_ESCAPE",
        )
        .await?;
        unchanged(&refusal, "the refused link outside the workspace").await?;
        let outside = refusal
            .directory("/outside")
            .entries()
            .await
            .map_err(step_failure)?;
        if outside.is_empty() {
            Ok(())
        } else {
            Err(check_failed(
                "dagger module init through a symbolic link",
                format!("wrote outside the workspace: {outside:?}"),
            ))
        }
    };

    let collision = async {
        let occupied = commit_all(
            &installed(cli, "/collision", runtime)
                .with_new_file(
                    crate_manifest("collision"),
                    "/collision/.dagger/modules/collision/Cargo.toml",
                )
                .with_file(
                    "/collision/.dagger/modules/collision/src/lib.rs",
                    fixtures.file("collision.rs"),
                )
                .with_new_file(
                    "fn caller_owned() {}\n",
                    "/collision/.dagger/modules/collision/src/bin/dagger-module.rs",
                ),
            "crate with its own src/bin/dagger-module.rs",
        );
        let refusal = refused(
            &occupied,
            &["-y", "module", "init", "rust", "--name", "collision"],
            "OWNERSHIP_CONFLICT",
        )
        .await?;
        unchanged(&refusal, "the refused ownership conflict").await
    };

    let credential = async {
        let manifest = format!(
            "{}rust-version = \"1.99.1\"\n\n[dependencies]\n\
             dagger-sdk = {{ package = \"tokeira-dagger-sdk\", \
             git = \"https://user:{CREDENTIAL}@{REPOSITORY}\", rev = \"{commit}\" }}\n",
            crate_manifest("credential")
        );
        let fixture = commit_all(
            &installed(cli, "/credential", runtime)
                .with_new_file(
                    manifest,
                    "/credential/.dagger/modules/credential/Cargo.toml",
                )
                .with_new_file(
                    "pub fn caller_owned() {}\n",
                    "/credential/.dagger/modules/credential/src/lib.rs",
                ),
            "crate whose dependency URL carries a credential",
        );
        let refusal = refused(
            &fixture,
            &["-y", "module", "init", "rust", "--name", "credential"],
            "SDK_DEPENDENCY_CONFLICT",
        )
        .await?;
        let output = refusal.combined_output().await.map_err(step_failure)?;
        if output.contains(CREDENTIAL) {
            return Err(check_failed(
                "the refused credential-bearing dependency",
                "printed the credential",
            ));
        }
        unchanged(&refusal, "the refused credential-bearing dependency").await
    };

    tokio::try_join!(escape, symlink, collision, credential)?;
    Ok(())
}

/// Step 11: a module configured by a legacy `dagger.json`, without generated files, loads and
/// answers a call. The runtime generates its code privately, so the workspace stays as it was.
async fn legacy_module(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
) -> Result<(), ModuleError> {
    let workspace = dagger(
        &installed(cli, "/legacy", runtime),
        &[
            "-y",
            "module",
            "init",
            "rust",
            "--name",
            "legacy",
            "--path",
            "modules/legacy",
        ],
    );
    let config = serde_json::json!({
        "name": "legacy",
        "engineVersion": format!("v{DAGGER_VERSION}"),
        "sdk": { "source": runtime },
    });
    // What a legacy module never had: the generated files and `dagger-module.toml`.
    let workspace = commit_all(
        &workspace
            .with_workdir("/legacy/modules/legacy")
            .with_exec(vec![
                "rm",
                "-r",
                "dagger-module.toml",
                ".dagger",
                "src/dagger_generated",
                "src/bin",
                ".gitattributes",
                ".gitignore",
            ])
            .with_workdir("/legacy")
            .with_file(
                "/legacy/modules/legacy/src/lib.rs",
                fixtures.file("legacy.rs"),
            )
            .with_new_file(config.to_string(), "/legacy/modules/legacy/dagger.json"),
        "legacy module",
    );
    let called = prints(
        &workspace,
        &["-m", "modules/legacy", "call", "probe"],
        "rust-sdk-protocol-ok",
    )
    .await?;
    unchanged(&called, "a call to the legacy module").await
}

/// The README's module, as readers copy it: generated into a sample service, then its
/// test against PostgreSQL, its build, and its reviewer, which is listed and composed as
/// `dagger agent` does and approves a change in a recorded review, so no model is involved.
/// Its publish needs a registry, so it is checked by hand.
async fn readme_module(
    cli: &Container,
    fixtures: &Directory,
    tree: &Directory,
    runtime: &str,
) -> Result<(), ModuleError> {
    let readme = tree.file("README.md").contents().await?;
    let module = marked_module(&readme)?;
    let service = installed(
        &cli.with_directory("/api", fixtures.directory("api")),
        "/api",
        runtime,
    );
    let service = commit_all(
        &dagger(&service, &["-y", "module", "init", "rust", "--name", "ci"]),
        "initialize ci module",
    )
    .with_new_file(module, "/api/.dagger/modules/ci/src/lib.rs");
    let service = commit_all(
        &dagger(&service, &["generate", "-y"]),
        "ci module functions",
    );

    let test = async {
        let report = dagger(&service, &["call", "ci", "test"])
            .stdout()
            .await
            .map_err(step_failure)?;
        if report.contains("test database_accepts_connections ... ok") {
            Ok(())
        } else {
            Err(check_failed(
                "dagger call ci test",
                format!("the database test did not pass:\n{}", tail(&report)),
            ))
        }
    };
    let build = prints(
        &service,
        &[
            "call",
            "ci",
            "build",
            "with-exec",
            "--args=/usr/local/bin/api",
            "stdout",
        ],
        "api 0.1.0",
    );
    let replay = format!("--model={}", approving_replay());
    let reviewer = async {
        prints(
            &service,
            &["agent", "--list", "--format", "link"],
            "dag+expertise://?expertise=ci/reviewer",
        )
        .await?;
        composed(
            &service,
            &["diff", "file", "test"],
            &["publish", "review", "reviewer"],
        )
        .await?;
        prints(&service, &["call", "ci", "review", &replay], APPROVAL).await
    };
    tokio::try_join!(test, build, reviewer)?;
    Ok(())
}

/// The reviewer's reply in `approving_replay`.
const APPROVAL: &str = "The change is sound.\n\nAPPROVE";

/// A model for the README module's `review` that replays a recorded conversation in which
/// the reviewer approves: one of the engine's `recording/` models, which need no provider.
fn approving_replay() -> String {
    let conversation = serde_json::json!([
        {"role": "USER", "content": [{"kind": "TEXT", "text": "Review the change."}]},
        {"role": "ASSISTANT", "content": [{"kind": "TEXT", "text": APPROVAL}]},
    ]);
    format!("recording/{}", base64(conversation.to_string().as_bytes()))
}

/// Standard base64, with padding.
fn base64(bytes: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut encoded = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let group = chunk
            .iter()
            .enumerate()
            .fold(0_u32, |group, (index, byte)| {
                group | (u32::from(*byte) << (16 - 8 * index))
            });
        for index in 0..4 {
            encoded.push(if index <= chunk.len() {
                char::from(ALPHABET[((group >> (18 - 6 * index)) & 63) as usize])
            } else {
                '='
            });
        }
    }
    encoded
}

/// The module block that `README_MARKER` introduces in the README.
fn marked_module(readme: &str) -> Result<String, ModuleError> {
    let unmarked =
        || ModuleError::new(format!("README.md has no Rust block after {README_MARKER}"));
    let (_, marked) = readme.split_once(README_MARKER).ok_or_else(unmarked)?;
    let (_, block) = marked.split_once("```rust\n").ok_or_else(unmarked)?;
    let (module, _) = block.split_once("\n```").ok_or_else(unmarked)?;
    Ok(format!("{module}\n"))
}

/// What the later-engine step shows when it passes.
fn later_passed() -> String {
    format!(
        "on an engine that reported v{LATER_ENGINE_VERSION} while it served the target's API \
         view, a module initialized with the commit's runtime declared the target release, \
         regenerated without changes, and answered calls, a collection query and a check; a \
         module that declared the later release was refused with the engineVersion to declare \
         instead; and a plain client accepted the engine"
    )
}

/// The later-engine step. The engine of the release the commit targets runs as a service of
/// the one that runs this module, and reports a later release while it serves the target's
/// API view, as a later release serves a view it keeps. The module half and the client half
/// run on it at once.
async fn later_engine_step(
    dag: &Query,
    cli: &Container,
    fixtures: &Directory,
    tree: &Directory,
    runtime: &str,
) -> Result<(), ModuleError> {
    let engine = later_engine_service(dag);
    // Started once for the whole step; a binding alone starts and stops it around each
    // command.
    engine.start().await.map_err(step_failure)?;
    let module_cli = on_later_engine(cli, &engine);
    let client = on_later_engine(&client_project(dag, cli, fixtures, tree), &engine);
    let step = tokio::try_join!(
        later_module(&module_cli, fixtures, runtime),
        later_client(&client),
    );
    // Stopping gracefully lets the engine close its databases before its state is reused.
    // The step's own failure is the one to report.
    let stopped = engine.stop().await.map_err(step_failure);
    step.and(stopped).map(|_| ())
}

/// The later-engine step's engine: the image of the release the SDK targets, reporting
/// `LATER_ENGINE_VERSION` for itself, on port 1234. Its state outlives the service in a cache
/// volume of the engine that runs it, which one engine at a time may use, so its build cache
/// stays warm between runs; it keeps 5 GB of that cache and collects above 15 GB.
fn later_engine_service(dag: &Query) -> Service {
    dag.container()
        .from(ENGINE_IMAGE)
        .with_env_variable("_EXPERIMENTAL_DAGGER_VERSION", LATER_ENGINE_VERSION)
        // An expired cache entry among those the image ships fails every start of the
        // release, so an empty directory hides them, as in `.dagger/engine.sh`.
        .with_mounted_temp("/usr/local/share/dagger/entries")
        .with_mounted_cache_opts(
            dag.cache_volume("ci-later-engine-state"),
            "/var/lib/dagger",
            &ContainerWithMountedCacheOpts::default().with_sharing(CacheSharingMode::Locked),
        )
        .with_exposed_port(1234)
        .as_service_opts(
            &ContainerAsServiceOpts::default()
                .with_args(vec![
                    "--addr",
                    "tcp://0.0.0.0:1234",
                    // Its containers' network, apart from those of the engine that runs it
                    // (10.87.0.0/16) and of Dagger's own development engines.
                    "--network-name",
                    "dagger-later",
                    "--network-cidr",
                    "10.89.0.0/16",
                    "--oci-worker-gc-keepstorage",
                    "5000,0,15000",
                ])
                .with_use_entrypoint(true)
                .with_insecure_root_capabilities(true),
        )
}

/// `container` with the later-engine step's engine bound as `later-engine`, which `dagger`
/// commands run `Via::LaterEngine` reach through DAGGER_ENGINE.
fn on_later_engine(container: &Container, engine: &Service) -> Container {
    container
        .with_service_binding("later-engine", engine.clone())
        .with_env_variable("DAGGER_ENGINE", "tcp://later-engine:1234")
}

/// The module half of the later-engine step. `dagger module init` declares the target
/// release, so the engine serves the module the target's API view: it regenerates without
/// changes beside the Dang module it depends on, and answers calls, a collection query and
/// a check. A module that declares the later release is served that release's view, which
/// generation refuses with the engineVersion to declare instead.
async fn later_module(
    cli: &Container,
    fixtures: &Directory,
    runtime: &str,
) -> Result<(), ModuleError> {
    let via = Via::LaterEngine;
    let gate = async {
        let module = initialized_via(via, cli, "gate", runtime);
        declares_target(
            &module,
            "/gate/.dagger/modules/gate/dagger-module.toml",
            "dagger module init rust --name gate on the later engine",
        )
        .await?;
        let workspace = module
            .with_file(
                "/gate/.dagger/modules/gate/src/lib.rs",
                fixtures.file("gate.rs"),
            )
            .with_new_file("rust module gate\n", "/gate/gate-input/note.txt");
        // The gate module's source calls the greeter, so it gets the greeter as its client
        // here too.
        let workspace = with_greeter(via, &workspace, fixtures, "/gate", "gate").await?;
        let workspace = commit_all(
            &dagger_via(via, &workspace, &["generate", "-y"]),
            "regenerate gate module",
        );
        let workspace = dagger_via(via, &workspace, &["generate", "-y"]);
        unchanged(&workspace, "a second dagger generate on the later engine").await?;
        tokio::try_join!(
            prints_via(
                via,
                &workspace,
                &["call", "gate", "note", "--source", "gate-input", "contents"],
                "rust module gate"
            ),
            prints_via(
                via,
                &workspace,
                &["call", "gate", "flip", "--protocol", "TCP"],
                "UDP"
            ),
            queried_via(via, &workspace, COLLECTION_QUERY, COLLECTION_EXPECTED),
            refused_via(
                via,
                &workspace,
                &["check", "gate/items/verify"],
                "unselected item c ran"
            ),
        )?;
        Ok(())
    };
    // A repository of its own, since it syncs other contents at the same time.
    let ahead = async {
        let module = initialized_via(via, cli, "ahead", runtime);
        let path = "/ahead/.dagger/modules/ahead/dagger-module.toml";
        let manifest = declares_target(
            &module,
            path,
            "dagger module init rust --name ahead on the later engine",
        )
        .await?;
        let module = module.with_new_file(
            manifest.replacen(
                &target_declaration(),
                &format!("engineVersion = \"v{LATER_VERSION}\"\n"),
                1,
            ),
            path,
        );
        refused_via(
            via,
            &module,
            &["generate", "-y"],
            &format!(
                "states the v{LATER_VERSION} API view, and this SDK requires the \
                 v{DAGGER_VERSION} view"
            ),
        )
        .await
    };
    tokio::try_join!(gate, ahead)?;
    Ok(())
}

/// The client half of the later-engine step: the acceptance's plain client, built from the
/// commit, accepts the later engine under `dagger run`, whose session has the target's API
/// view because the CLI is of the target release.
async fn later_client(client: &Container) -> Result<(), ModuleError> {
    client_run_via(
        Via::LaterEngine,
        client,
        "acceptance-client",
        ContainerWithExecOpts::default(),
        &format!("ACCEPTANCE-CLIENT-OK v{LATER_ENGINE_VERSION}"),
    )
    .await
    .map(|_| ())
}

/// The pinned toolchain with Cargo's download cache.
fn rust(dag: &Query) -> Container {
    dag.container().from(RUST_IMAGE).with_mounted_cache(
        dag.cache_volume("cargo-registry"),
        "/usr/local/cargo/registry",
    )
}

/// The version a commit releases. The crates it publishes must be exactly `PUBLISHED`, at
/// one version, each with the metadata crates.io displays.
async fn release_version(dag: &Query, tree: &Directory) -> Result<String, ModuleError> {
    let metadata = rust(dag)
        .with_directory("/src", tree.clone())
        .with_workdir("/src")
        .with_exec(vec![
            "cargo",
            "metadata",
            "--format-version",
            "1",
            "--no-deps",
            "--locked",
        ])
        .stdout()
        .await
        .map_err(step_failure)?;
    let metadata: Value = serde_json::from_str(&metadata)
        .map_err(|error| ModuleError::new(format!("cargo metadata: {error}")))?;
    let mut published = BTreeMap::new();
    for package in metadata["packages"].as_array().into_iter().flatten() {
        // `publish` is null when any registry may take the crate, and empty for
        // `publish = false`.
        if package["publish"].as_array().is_some_and(Vec::is_empty) {
            continue;
        }
        let name = package["name"].as_str().unwrap_or_default();
        for field in [
            "description",
            "license",
            "repository",
            "readme",
            "rust_version",
        ] {
            if package[field].as_str().is_none_or(str::is_empty) {
                return Err(ModuleError::new(format!(
                    "{name} has no {field}, which crates.io displays"
                )));
            }
        }
        let version = package["version"].as_str().unwrap_or_default();
        published.insert(name.to_owned(), version.to_owned());
    }
    let expected: BTreeSet<&str> = PUBLISHED.into_iter().collect();
    if !published.keys().map(String::as_str).eq(expected) {
        return Err(ModuleError::new(format!(
            "the workspace publishes {:?}, not {PUBLISHED:?}",
            published.keys().collect::<Vec<_>>()
        )));
    }
    let versions: BTreeSet<&String> = published.values().collect();
    match versions.into_iter().collect::<Vec<_>>()[..] {
        [version] => Ok(version.clone()),
        _ => Err(ModuleError::new(format!(
            "the published crates must share one version: {published:?}"
        ))),
    }
}

/// Refuses a version crates.io already lists: a published version is never replaced, so a
/// fix needs a new one.
async fn unpublished(dag: &Query, version: &str) -> Result<(), ModuleError> {
    // Never cached, so every run reads the index afresh.
    let now = dag.current_timestamp().await?;
    for name in PUBLISHED {
        let url = format!("https://index.crates.io/{}", sparse_index_path(name));
        let lookup = dag
            .container()
            .from(RUST_IMAGE)
            .with_env_variable("LOOKED_UP_AT", now.as_str())
            .with_exec(vec![
                "curl",
                "--silent",
                "--show-error",
                "--output",
                "/tmp/index",
                "--write-out",
                "%{http_code}",
                url.as_str(),
            ]);
        match lookup.stdout().await.map_err(step_failure)?.as_str() {
            // crates.io has never published the crate.
            "404" => {}
            "200" => {
                let index = lookup.file("/tmp/index").contents().await?;
                // Each line of the index describes one published version.
                if index.lines().any(|line| {
                    serde_json::from_str::<Value>(line).is_ok_and(|entry| entry["vers"] == version)
                }) {
                    return Err(ModuleError::new(format!(
                        "crates.io already has {name} {version}; a release needs a new version"
                    )));
                }
            }
            status => {
                return Err(ModuleError::new(format!("{url} answered HTTP {status}")));
            }
        }
    }
    Ok(())
}

/// Where the crates.io sparse index lists a crate.
fn sparse_index_path(name: &str) -> String {
    match name.len() {
        1 => format!("1/{name}"),
        2 => format!("2/{name}"),
        3 => format!("3/{}/{name}", &name[..1]),
        _ => format!("{}/{}/{name}", &name[..2], &name[2..4]),
    }
}

/// Packages the published crates in one `cargo package`, which verifies each by building
/// it from its archive, the SDK against the packaged macros crate. Returns the archives,
/// their SHA256SUMS, and each crate's `cargo package --list`, once each archive is within
/// crates.io's limit and records the clean commit it came from.
async fn archives(
    dag: &Query,
    tree: &Directory,
    commit: &str,
    version: &str,
) -> Result<Directory, ModuleError> {
    let mut command = vec!["cargo", "package", "--locked"];
    for name in PUBLISHED {
        command.extend(["-p", name]);
    }
    let packaged = rust(dag)
        .with_directory("/src", tree.clone())
        .with_workdir("/src")
        .with_exec(command);
    // The tests the archives leave out each draw a notice; any other warning stops here.
    let log = packaged.stderr().await.map_err(step_failure)?;
    let warnings: Vec<&str> = log
        .lines()
        .filter(|line| {
            line.starts_with("warning:")
                && !(line.starts_with("warning: ignoring test ")
                    && line.ends_with(" is not included in the published package"))
        })
        .collect();
    if !warnings.is_empty() {
        return Err(check_failed(
            "cargo package",
            format!("warned:\n{}", warnings.join("\n")),
        ));
    }

    let mut release = packaged.with_exec(vec!["mkdir", "/release"]);
    for name in PUBLISHED {
        let files = packaged
            .with_exec(vec!["cargo", "package", "--locked", "--list", "-p", name])
            .stdout()
            .await
            .map_err(step_failure)?;
        let archive = format!("target/package/{name}-{version}.crate");
        release = release
            .with_new_file(files, format!("/release/{name}-{version}.files"))
            .with_exec(vec!["cp", archive.as_str(), "/release/"]);
    }
    let release = release.with_workdir("/release").with_exec(vec![
        "sh",
        "-c",
        "sha256sum *.crate > SHA256SUMS",
    ]);
    for name in PUBLISHED {
        let archive = format!("{name}-{version}.crate");
        let size = release.file(format!("/release/{archive}")).size().await?;
        if size > ARCHIVE_LIMIT {
            return Err(check_failed(
                &archive,
                format!("is {size} bytes, over crates.io's limit of {ARCHIVE_LIMIT}"),
            ));
        }
        let record = release
            .with_exec(vec![
                "tar",
                "-xzOf",
                archive.as_str(),
                format!("{name}-{version}/.cargo_vcs_info.json").as_str(),
            ])
            .stdout()
            .await
            .map_err(step_failure)?;
        let record: Value = serde_json::from_str(&record)
            .map_err(|error| check_failed(&archive, format!("has no VCS record: {error}")))?;
        if record["git"]["sha1"] != commit || record["git"]["dirty"] == true {
            return Err(check_failed(
                &archive,
                format!("records {record}, not the clean commit {commit}"),
            ));
        }
    }
    Ok(release.directory("/release"))
}

/// Builds the consumer application against the published crates, from the archives
/// `package` returned when given them and from crates.io otherwise, checks where its crates
/// came from, and runs it as a new session of this engine.
async fn consumer(
    dag: &Query,
    source: &Directory,
    engine: &str,
    version: &str,
    archives: Option<&Directory>,
) -> Result<(), ModuleError> {
    let mut app = dagger_cli(dag)
        .await?
        .with_mounted_cache(
            dag.cache_volume("cargo-registry"),
            "/usr/local/cargo/registry",
        )
        .with_new_file(
            consumer_manifest(version, archives.is_some()),
            "/consumer/Cargo.toml",
        )
        .with_file(
            "/consumer/src/main.rs",
            source.file(".dagger/modules/ci/consumer/main.rs"),
        );
    if let Some(archives) = archives {
        app = app
            .with_directory("/release", archives.clone())
            .with_exec(vec!["mkdir", "/archives"]);
        for name in PUBLISHED {
            let archive = format!("/release/{name}-{version}.crate");
            app = app.with_exec(vec!["tar", "-xzf", archive.as_str(), "-C", "/archives"]);
        }
    }
    let app = app
        .with_workdir("/consumer")
        .with_exec(vec!["cargo", "generate-lockfile"]);
    let metadata = app
        .with_exec(vec![
            "cargo",
            "metadata",
            "--format-version",
            "1",
            "--locked",
        ])
        .stdout()
        .await
        .map_err(step_failure)?;
    resolved(&metadata, version, archives.is_some())?;
    let built = app.with_exec(vec!["cargo", "build", "--locked"]);
    let output = dagger(&built, &["run", "cargo", "run", "--locked", "--quiet"])
        .stdout()
        .await
        .map_err(step_failure)?;
    let expected = format!("CONSUMER-OK {engine} hello consumer");
    if output.lines().any(|line| line == expected) {
        Ok(())
    } else {
        Err(check_failed(
            "the consumer",
            format!("printed no `{expected}`:\n{}", tail(&output)),
        ))
    }
}

/// The consumer's manifest: the SDK by version alone, as an application depends on it, in a
/// workspace of its own. With `archives`, the published crates resolve from the unpacked
/// archives instead of crates.io.
fn consumer_manifest(version: &str, archives: bool) -> String {
    let mut manifest = format!(
        "[package]\nname = \"consumer\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\
         publish = false\n\n[workspace]\n\n[dependencies]\n\
         tokeira-dagger-sdk = \"={version}\"\n\
         tokio = {{ version = \"1\", features = [\"macros\", \"rt-multi-thread\"] }}\n"
    );
    if archives {
        manifest.push_str("\n[patch.crates-io]\n");
        for name in PUBLISHED {
            manifest.push_str(&format!(
                "{name} = {{ path = \"/archives/{name}-{version}\" }}\n"
            ));
        }
    }
    manifest
}

/// Checks the consumer's resolved crates: each published crate once, at the release
/// version, from the archives or from crates.io as asked, and every other crate from
/// crates.io, so nothing comes from Git or a path.
fn resolved(metadata: &str, version: &str, archives: bool) -> Result<(), ModuleError> {
    let metadata: Value = serde_json::from_str(metadata)
        .map_err(|error| ModuleError::new(format!("the consumer's cargo metadata: {error}")))?;
    let packages: Vec<&Value> = metadata["packages"]
        .as_array()
        .into_iter()
        .flatten()
        .collect();
    for package in &packages {
        let name = package["name"].as_str().unwrap_or_default();
        let local = name == "consumer" || (archives && PUBLISHED.contains(&name));
        let source = package["source"].as_str();
        let expected = match source {
            None => local,
            Some(source) => !local && source == CRATES_IO,
        };
        if !expected {
            return Err(check_failed(
                "the consumer",
                format!(
                    "resolved {name} {} from {}",
                    package["version"],
                    source.unwrap_or("a path")
                ),
            ));
        }
    }
    for name in PUBLISHED {
        let versions: Vec<&str> = packages
            .iter()
            .filter(|package| package["name"] == name)
            .filter_map(|package| package["version"].as_str())
            .collect();
        if versions != [version] {
            return Err(check_failed(
                "the consumer",
                format!("resolved {name} at {versions:?}, not {version}"),
            ));
        }
    }
    Ok(())
}

/// A release's version and each published crate's SHA-256, as `package` recorded them.
struct ReleaseSums {
    version: String,
    archives: Vec<(&'static str, String)>,
}

/// The release read from a SHA256SUMS that `package` returned.
fn release_sums(sums: &str) -> Result<ReleaseSums, ModuleError> {
    let unexpected =
        |line: &str| ModuleError::new(format!("SHA256SUMS has an unexpected line: {line:?}"));
    let mut version: Option<&str> = None;
    let mut archives = Vec::new();
    for line in sums.lines() {
        let (sha256, file) = line.split_once("  ").ok_or_else(|| unexpected(line))?;
        let (name, release) = file
            .strip_suffix(".crate")
            .and_then(|archive| {
                PUBLISHED.into_iter().find_map(|name| {
                    let release = archive.strip_prefix(name)?.strip_prefix('-')?;
                    release
                        .starts_with(|first: char| first.is_ascii_digit())
                        .then_some((name, release))
                })
            })
            .ok_or_else(|| unexpected(line))?;
        if sha256.len() != 64 || !sha256.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return Err(unexpected(line));
        }
        if *version.get_or_insert(release) != release {
            return Err(ModuleError::new(
                "SHA256SUMS names more than one version".to_owned(),
            ));
        }
        archives.push((name, sha256.to_owned()));
    }
    let named: BTreeSet<&str> = archives.iter().map(|(name, _)| *name).collect();
    match version {
        Some(version) if archives.len() == PUBLISHED.len() && named.len() == PUBLISHED.len() => {
            Ok(ReleaseSums {
                version: version.to_owned(),
                archives,
            })
        }
        _ => Err(ModuleError::new(format!(
            "SHA256SUMS must name each of {PUBLISHED:?} once"
        ))),
    }
}

/// A Git repository at `path` that commits whatever the container already holds there, as
/// beta.27's workspaces require. The engine caches the directories a session syncs by path
/// and by the client ID that the first `dagger` command stores in the container, so
/// sessions that run at once and sync different contents each need a repository of their
/// own.
fn repository(container: &Container, path: &str) -> Container {
    commit_all(
        &container
            .with_exec(vec!["git", "init", "--quiet", path])
            .with_workdir(path),
        "initialize workspace",
    )
}

/// A new repository at `path`, as `repository` makes it, with the runtime installed and the
/// installation committed.
fn installed(container: &Container, path: &str, runtime: &str) -> Container {
    installed_via(Via::NewSession, container, path, runtime)
}

/// `installed`, with `dagger` reaching its engine `via`.
fn installed_via(via: Via, container: &Container, path: &str, runtime: &str) -> Container {
    commit_all(
        &dagger_via(via, &repository(container, path), &["install", runtime]),
        "install the runtime",
    )
}

/// A new repository at `/<name>`, as `installed` makes it, with a module named `name`
/// initialized and committed.
fn initialized(cli: &Container, name: &str, runtime: &str) -> Container {
    initialized_via(Via::NewSession, cli, name, runtime)
}

/// `initialized`, with `dagger` reaching its engine `via`.
fn initialized_via(via: Via, cli: &Container, name: &str, runtime: &str) -> Container {
    commit_all(
        &dagger_via(
            via,
            &installed_via(via, cli, &format!("/{name}"), runtime),
            &["-y", "module", "init", "rust", "--name", name],
        ),
        "initialize module",
    )
}

/// The engineVersion line that `dagger module init` writes: the release the SDK targets.
fn target_declaration() -> String {
    format!("engineVersion = \"v{DAGGER_VERSION}\"\n")
}

/// Checks that the module manifest at `path` declares the release the SDK targets, as
/// `dagger module init` writes it, and returns the manifest.
async fn declares_target(
    module: &Container,
    path: &str,
    check: &str,
) -> Result<String, ModuleError> {
    let manifest = module.file(path).contents().await.map_err(step_failure)?;
    let declared = target_declaration();
    if manifest.contains(&declared) {
        Ok(manifest)
    } else {
        Err(check_failed(
            check,
            format!("dagger-module.toml does not declare {declared:?}:\n{manifest}"),
        ))
    }
}

/// Gives the module `name`, in the repository at `root`, a dependency on `greeter`, the
/// acceptance's Dang module, so the dependency needs no Rust build. It copies the greeter
/// beside the module and runs `dagger module client add ../greeter` from the module's
/// directory, with `dagger` reaching its engine `via`. The command records the greeter as
/// a client of the module's scope in `dagger.toml`, and generation then makes the scope's
/// clients the module's dependencies and regenerates the module.
async fn with_greeter(
    via: Via,
    workspace: &Container,
    fixtures: &Directory,
    root: &str,
    name: &str,
) -> Result<Container, ModuleError> {
    let module = format!("{root}/.dagger/modules/{name}");
    let args = ["module", "client", "add", "-y", "../greeter"];
    let added = dagger_via(
        via,
        &workspace
            .with_directory(
                format!("{root}/.dagger/modules/greeter"),
                fixtures.directory("greeter"),
            )
            .with_workdir(module.as_str()),
        &args,
    )
    .with_workdir(root);
    let (manifest, config) = tokio::try_join!(
        file_contents(&added, format!("{module}/dagger-module.toml")),
        file_contents(&added, format!("{root}/dagger.toml")),
    )?;
    let check = format!("dagger {} in .dagger/modules/{name}", args.join(" "));
    // Exactly one table, with nothing more in it.
    let sole = manifest.matches("[[dependencies]]").count() == 1
        && manifest
            .split_once(GREETER_DEPENDENCY)
            .is_some_and(|(before, after)| {
                before.ends_with('\n') && (after.is_empty() || after.starts_with(['\n', '[']))
            });
    if !sole {
        return Err(check_failed(
            &check,
            format!(
                "the module's dagger-module.toml does not have exactly the dependency \
                 {GREETER_DEPENDENCY:?}:\n{manifest}"
            ),
        ));
    }
    let recorded = recorded_clients(&config, &format!(".dagger/modules/{name}"));
    if recorded != ["./.dagger/modules/greeter"] {
        return Err(check_failed(
            &check,
            format!(
                "dagger.toml records {recorded:?} for the module's scope, not \
                 ./.dagger/modules/greeter alone:\n{config}"
            ),
        ));
    }
    Ok(added)
}

/// Adds `caller`, the acceptance's Dang module, to the repository at `root`, with a
/// dependency on the module `name` there. No workspace configuration names it, so a
/// command loads it with `-m` and generation never rewrites its dependency.
fn with_caller(workspace: &Container, fixtures: &Directory, root: &str, name: &str) -> Container {
    let caller = format!("{root}/.dagger/modules/caller");
    workspace
        .with_new_file(
            format!(
                "{}\n[[dependencies]]\nname = \"{name}\"\nsource = \"../{name}\"\n",
                dang_manifest("caller")
            ),
            format!("{caller}/dagger-module.toml"),
        )
        .with_file(format!("{caller}/main.dang"), fixtures.file("caller.dang"))
}

/// The manifest of a Dang module named `name` that declares the release the SDK targets,
/// in the form Dagger's manifest helper writes.
fn dang_manifest(name: &str) -> String {
    format!(
        "name = \"{name}\"\n{}\n[runtime]\nsource = \"dang\"\n",
        target_declaration()
    )
}

/// The manifest of a crate named `name` with no dependencies.
fn crate_manifest(name: &str) -> String {
    format!("[package]\nname = \"{name}\"\nversion = \"0.1.0\"\nedition = \"2024\"\n")
}

/// Commits every change in the repository at the working directory.
fn commit_all(container: &Container, message: &str) -> Container {
    container
        .with_exec(vec!["git", "add", "--all"])
        .with_exec(vec![
            "git",
            "commit",
            "--quiet",
            "--allow-empty",
            "--message",
            message,
        ])
}

/// How a `dagger` command reaches its engine.
#[derive(Clone, Copy)]
enum Via {
    /// As a new session of the engine that runs this module.
    NewSession,
    /// Through DAGGER_ENGINE, to the later-engine step's engine that `on_later_engine` binds.
    /// The command has no access to the engine that runs this module, so it cannot reach that
    /// one instead.
    LaterEngine,
}

impl Via {
    /// `opts` with the access to an engine that the command needs.
    fn exec_opts(self, opts: ContainerWithExecOpts) -> ContainerWithExecOpts {
        match self {
            Via::NewSession => opts.with_dagger_in_dagger_new_session(true),
            Via::LaterEngine => opts.with_disable_dagger_in_dagger(true),
        }
    }
}

/// Runs `dagger <args>` connected to this engine as a new session.
fn dagger(container: &Container, args: &[&str]) -> Container {
    dagger_via(Via::NewSession, container, args)
}

/// Runs `dagger <args>` connected to the engine it reaches `via`.
fn dagger_via(via: Via, container: &Container, args: &[&str]) -> Container {
    container.with_exec_opts(
        dagger_command(args),
        &via.exec_opts(ContainerWithExecOpts::default()),
    )
}

/// The command line of `dagger <args>`.
fn dagger_command<'a>(args: &[&'a str]) -> Vec<&'a str> {
    let mut command = vec!["dagger"];
    command.extend_from_slice(args);
    command
}

/// Runs `dagger <args>` and checks what it prints, less the final newline. Returns the
/// container as the command left it.
async fn prints(
    container: &Container,
    args: &[&str],
    expected: &str,
) -> Result<Container, ModuleError> {
    prints_via(Via::NewSession, container, args, expected).await
}

/// `prints`, with `dagger` reaching its engine `via`.
async fn prints_via(
    via: Via,
    container: &Container,
    args: &[&str],
    expected: &str,
) -> Result<Container, ModuleError> {
    let run = dagger_via(via, container, args);
    let output = run.stdout().await.map_err(step_failure)?;
    if output.trim_end() == expected {
        Ok(run)
    } else {
        Err(check_failed(
            &format!("dagger {}", args.join(" ")),
            format!("printed {output:?}, not {expected:?}"),
        ))
    }
}

/// Checks the description that the engine gives the module at `path`.
async fn described(container: &Container, path: &str, expected: &str) -> Result<(), ModuleError> {
    let query = format!("{{ moduleSource(refString: {path:?}) {{ asModule {{ description }} }} }}");
    let output = dagger(
        &container.with_new_file(query, "/description.graphql"),
        &["api", "query", "--doc", "/description.graphql"],
    )
    .stdout()
    .await
    .map_err(step_failure)?;
    let check = format!("the description of {path}");
    let response: Value = serde_json::from_str(&output)
        .map_err(|error| check_failed(&check, format!("the query printed no JSON: {error}")))?;
    match response["moduleSource"]["asModule"]["description"].as_str() {
        Some(description) if description == expected => Ok(()),
        Some(description) => Err(check_failed(
            &check,
            format!("is {description:?}, not {expected:?}"),
        )),
        None => Err(check_failed(&check, format!("is missing from {output:?}"))),
    }
}

/// Composes the workspace's one agent function into a conversation, as `dagger agent` does
/// before it prompts, and checks that the conversation offers each tool in `offered` and
/// none in `withheld`. Composing needs no model.
async fn composed(
    container: &Container,
    offered: &[&str],
    withheld: &[&str],
) -> Result<(), ModuleError> {
    let pipeline = "llm | compose $(current-workspace | artifacts | filter-types Expertise | one | value) | tools";
    let output = dagger(container, &["-c", pipeline])
        .stdout()
        .await
        .map_err(step_failure)?;
    let tools: Vec<&str> = output
        .lines()
        .filter_map(|line| line.strip_prefix("## "))
        .collect();
    if offered.iter().all(|tool| tools.contains(tool))
        && !withheld.iter().any(|tool| tools.contains(tool))
    {
        Ok(())
    } else {
        Err(check_failed(
            &format!("dagger -c {pipeline:?}"),
            format!("offered the tools {tools:?}"),
        ))
    }
}

/// Runs `dagger <args>`, which must fail and say `reason`, and returns the container as
/// the failure left it.
async fn refused(
    container: &Container,
    args: &[&str],
    reason: &str,
) -> Result<Container, ModuleError> {
    refused_via(Via::NewSession, container, args, reason).await
}

/// `refused`, with `dagger` reaching its engine `via`.
async fn refused_via(
    via: Via,
    container: &Container,
    args: &[&str],
    reason: &str,
) -> Result<Container, ModuleError> {
    let refusal = container.with_exec_opts(
        dagger_command(args),
        &via.exec_opts(ContainerWithExecOpts::default().with_expect(ReturnType::Failure)),
    );
    let check = format!("dagger {}", args.join(" "));
    let output = refusal.combined_output().await.map_err(|error| {
        if let QueryError::Exec { error: exec, .. } = &error
            && exec.exit_code() == Some(0)
        {
            return check_failed(
                &check,
                format!(
                    "succeeded, but must fail:\n{}",
                    tail(exec.stdout().unwrap_or_default())
                ),
            );
        }
        step_failure(error)
    })?;
    if output.contains(reason) {
        Ok(refusal)
    } else {
        Err(check_failed(
            &check,
            format!("failed without saying {reason:?}:\n{}", tail(&output)),
        ))
    }
}

/// Checks that the repository at the working directory has no changes.
async fn unchanged(container: &Container, check: &str) -> Result<(), ModuleError> {
    let status = container
        .with_exec(vec!["git", "status", "--porcelain"])
        .stdout()
        .await
        .map_err(step_failure)?;
    if status.is_empty() {
        Ok(())
    } else {
        Err(check_failed(
            check,
            format!("changed the workspace:\n{status}"),
        ))
    }
}

/// The contents of the file at `path` in `container`.
async fn file_contents(
    container: &Container,
    path: impl Into<String>,
) -> Result<String, ModuleError> {
    let file = container.file(path.into());
    file.contents().await.map_err(step_failure)
}

/// The entries of the directory at `path` in `container`, a directory's with a final `/`.
async fn directory_entries(
    container: &Container,
    path: impl Into<String>,
) -> Result<Vec<String>, ModuleError> {
    let directory = container.directory(path.into());
    directory.entries().await.map_err(step_failure)
}

/// The JSON document at `path` in `tree`.
async fn json_file(tree: &Directory, path: &str) -> Result<Value, ModuleError> {
    let text = tree.file(path).contents().await?;
    serde_json::from_str(&text).map_err(|error| ModuleError::new(format!("{path}: {error}")))
}

/// The string `key` of the JSON object read from `path`.
fn string_field<'a>(json: &'a Value, path: &str, key: &str) -> Result<&'a str, ModuleError> {
    json.get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| ModuleError::new(format!("{path} has no string {key}")))
}

/// An acceptance check that ran but did not hold.
fn check_failed(check: &str, detail: impl std::fmt::Display) -> ModuleError {
    ModuleError::new(format!("{check}: {detail}"))
}

/// Reports a failed step with its command, exit code, and the end of its output, so that
/// the message alone says what failed, wherever it is read. A step whose argument failed
/// to resolve reports that argument's failure.
fn step_failure(error: QueryError) -> ModuleError {
    if let QueryError::Build(build) = &error
        && let Some(cause) =
            std::error::Error::source(build).and_then(|cause| cause.downcast_ref::<QueryError>())
    {
        return step_failure(cause.clone());
    }
    let QueryError::Exec { error: exec, .. } = &error else {
        return error.into();
    };
    let command = exec.command().unwrap_or_default().join(" ");
    let status = exec
        .exit_code()
        .map_or_else(String::new, |code| format!(" with exit code {code}"));
    let stdout = tail(exec.stdout().unwrap_or_default());
    let stderr = tail(exec.stderr().unwrap_or_default());
    ModuleError::new(format!("{command} failed{status}\n{stdout}\n{stderr}"))
}

/// The last `OUTPUT_TAIL` bytes of `output`, starting on a character boundary.
fn tail(output: &str) -> &str {
    let mut start = output.len().saturating_sub(OUTPUT_TAIL);
    while !output.is_char_boundary(start) {
        start += 1;
    }
    &output[start..]
}
